export function clamp(value        , low        , high        )         {
  return Math.max(low, Math.min(high, value));
}

// Wheel speeds for one of the four drive buttons. Turning spins on the spot: a faster right
// wheel turns the rover left, as in the protocol.
export function driveFor(direction           , speed        )         {
  const s = clamp(speed, 0, 1);
  switch (direction) {
    case "forward":
      return { left: s, right: s };
    case "back":
      return { left: -s, right: -s };
    case "left":
      return { left: -s, right: s };
    case "right":
      return { left: s, right: -s };
  }
}

export function keyDirection(key        )                   {
  switch (key.toLowerCase()) {
    case "w":
    case "arrowup":
      return "forward";
    case "s":
    case "arrowdown":
      return "back";
    case "a":
    case "arrowleft":
      return "left";
    case "d":
    case "arrowright":
      return "right";
    default:
      return null;
  }
}

const HEADLINES                         = {
  scanning: "Looking at the scene.",
  need_survivor: "Find the survivor.",
  plan_ready: "Check the plan, then approve it.",
  blocked: "There is no safe way through.",
  clear: "The way is already clear.",
  waiting: "Waiting for the rover.",
  running: "The rover is clearing the way.",
  verifying: "Checking the result.",
  aborted: "The run was stopped.",
};

const FALLBACK_HEADLINE = "Looking at the scene.";

export function headlineFor(phase        , verified                )         {
  if (phase === "done") {
    return verified ? "The way is clear." : "The rover finished, but it is not confirmed.";
  }
  return HEADLINES[phase] ?? FALLBACK_HEADLINE;
}

// What to tell the person when the laptop cannot reach the rover, or null when it can.
export function roverNotice(connected         , address        , error        )                {
  if (connected) return null;
  const detail = error ? ` (${error})` : "";
  return `Not connected to the rover at ${address}. Nothing can be sent until it is.${detail}`;
}

// The status line: why the last run was stopped (if it was), then what is happening now.
export function withNotice(notice               , message        )         {
  return notice ? `${notice} ${message}` : message;
}

const WARN_PHASES = ["blocked", "aborted", "need_survivor"];

export function toneFor(phase        , linkUp         , verified                , cameraError               )       {
  if (verified === true) return "ok";
  if (WARN_PHASES.includes(phase) || !linkUp || cameraError || verified === false) return "warn";
  return "";
}

// One line of the "learning across runs" list: what a finished run did, and what the laptop took from it.
                               
                 
                
                  
                         
                      
                           
 

export function episodeLine(episode              )                                              {
  const left = `Run ${episode.number}: moved ${episode.moved} block${episode.moved === 1 ? "" : "s"}`;
  if (episode.outcome === "bumped") {
    return {
      left,
      right: `brushed ${episode.brushed ?? "a block"}, next corridor ${episode.next_corridor_mm} mm`,
      tone: "warn",
    };
  }
  if (episode.outcome === "clean") {
    return { left, right: `clean, corridor ${episode.corridor_mm} mm`, tone: "ok" };
  }
  return { left, right: "the camera could not confirm the way is clear", tone: "warn" };
}

export const BUSY_PHASES = ["waiting", "running", "verifying"];
export const END_PHASES = ["done", "aborted"];

// --- The Manual tab talks straight to the rover's own Wi-Fi (firmware/rover_arm_ap.cpp) ---------

                                                                                                       

// Both boards join the same phone hotspot and announce these names (rover_arm_ap.cpp, rover_link.cpp).
// If the name does not resolve on a network, type the IP the board prints on its serial port.
export const DEFAULT_ROVER_ADDRESS = "still-arm.local";
export const DEFAULT_CAMERA_ADDRESS = "still-here.local";
export const SERVO_COUNT = 5; // base, shoulder, elbow, wrist, gripper

const DRIVE_CODES                                 = {
  forward: "F",
  back: "B",
  left: "L",
  right: "R",
  "forward-left": "Q",
  "forward-right": "E",
  "back-left": "Z",
  "back-right": "C",
};

// The one-letter code the rover's /drive endpoint understands. "S" is stop.
export function driveCode(direction                )         {
  return DRIVE_CODES[direction];
}

// The speed slider is 10 to 100 percent; the rover wants 100 to 255 (below 100 the motors just hum).
export function driveSpeedValue(percent        )         {
  const p = clamp(percent, 10, 100);
  return Math.round(100 + ((p - 10) / 90) * 155);
}

// What a person typed for the rover's address, as host or host:port, or null if it cannot be one.
// Accepts "192.168.4.1", "http://192.168.4.1/" and "rover.local:80". Nothing else is let through,
// so a typo can never send commands somewhere unexpected.
export function cleanAddress(text        )                {
  const bare = text.trim().replace(/^https?:\/\//i, "").replace(/\/.*$/, "");
  return /^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:\d{1,5})?$/.test(bare) ? bare : null;
}

                                                          

export function roverUrl(address        , path        , params              = {})         {
  const query = Object.entries(params)
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join("&");
  return `http://${address}${path}${query === "" ? "" : `?${query}`}`;
}

// Where the camera board serves its video (mjpeg_server.cpp).
export function streamUrl(address        )         {
  return roverUrl(address, "/stream");
}

                           
                                                         
                
                
 

// The rover's /state answer, or null when it is not what we expect (so the page can say so).
export function parseArmState(data         )                  {
  if (typeof data !== "object" || data === null) return null;
  const record = data                           ;
  const lists             = [];
  for (const key of ["a", "min", "max"]) {
    const list = record[key];
    if (!Array.isArray(list) || list.length !== SERVO_COUNT || !list.every((n) => typeof n === "number" && Number.isFinite(n))) {
      return null;
    }
    lists.push(list            );
  }
  const [a, min, max] = lists;
  if (!a || !min || !max) return null;
  return { a, min, max };
}

// A click or tap on the picture, as a position in the camera's own pixels.
export function toFrame(clientX        , clientY        , box     , frame                          ) {
  return {
    x: ((clientX - box.left) * frame.w) / box.width,
    y: ((clientY - box.top) * frame.h) / box.height,
  };
}

// Where a marker laid over a picture shown at a different size belongs, in CSS pixels.
export function toDisplay(point                  , boxWidth        , frameWidth        ) {
  const scale = boxWidth / frameWidth;
  return { left: point[0] * scale, top: point[1] * scale };
}
